"""Build a reviewed source-location manifest and short factual abstracts.
Usage: python scripts/prepare-neighborhood-expansion.py /absolute/research-cache
Raw source pages remain in the research cache, outside Git and the deployed Site.
"""
from pathlib import Path
from lxml import html
from datetime import datetime,timezone
import json,sys,hashlib,re
ROOT=Path(__file__).resolve().parents[1];CACHE=Path(sys.argv[1]);MASTER={g['name']:g['dongs'] for g in json.loads((ROOT/'data/seoul-regions.json').read_text())['districts']};ROWS=[]
CHECKED='2026-10-17';UNCHECKED='개별 자료의 복제·변형 이용허락 미확인. 원문·이미지 보관과 재사용 허용은 설정하지 않음. 지명·연혁의 짧은 사실 요약만 별도로 작성했으며 전승·추정·상충은 구분함. AI 작성이 원자료의 권리를 없애는 것으로 취급하지 않음.'
def add(key,gu,title,url,sections,notes='',rights='unknown',web=False):
 p=CACHE/(key+'.html');body='';raw=None
 if not web:
  raw=p.read_bytes()
  try:decoded=raw.decode('utf-8')
  except UnicodeDecodeError:decoded=raw.decode('cp949')
  doc=html.fromstring(decoded);[x.drop_tree() for x in doc.xpath('//script|//style')];body=' '.join(doc.text_content().split())
  if rights=='KOGL1':assert doc.xpath('//a[contains(@href,"licenseType1.do")]'),key
  captured=datetime.fromtimestamp(p.stat().st_mtime,timezone.utc).isoformat()
 else:captured=datetime.now(timezone.utc).isoformat() # Web verification recorded while preparing the checked manifest; no source HTML hash claimed.
 prepared=[]
 for item in sections:
  label,text,locator=item[:3];anchor=item[3] if len(item)>3 else label
  if body:assert re.sub(r'\s','',anchor) in re.sub(r'\s','',body),(key,label,anchor)
  exact=label in MASTER[gu]
  prepared.append({'text':text,'locator':locator,'textKind':'paraphrase','regionIds':['dong-'+gu+'-'+label] if exact else ['gu-'+gu],'regionLabel':label,'relation':'exact_name' if exact else 'district_context','basis':('공식 본문에서 '+anchor+' 표기와 해당 구의 법정동 명칭을 대조. 지역 분류이며 경계·부지 동일성은 미검증.' if exact else '공식자료의 공통 동명·행정동 또는 옛 지명. 현재 세부 법정동으로 확대하지 않음.')})
 note=('2026-10-17 해당 페이지의 공공누리 제1유형 링크와 표시 확인. 출처 표시 조건을 유지하며 본문은 별도 사실 요약, 내용 검토 대기.' if rights=='KOGL1' else UNCHECKED)
 method='공식 페이지 직접 조회 · 원본 HTML SHA-256 기록' if not web else '공식 상세 페이지 웹 열람 도구로 본문 확인 · 별도 HTTP 클라이언트 요청 502 · 원본 HTML 지문 미기록'
 ROWS.append({'source':{'title':title,'institution':gu+'청','providerId':'','url':url,'kind':'web','summary':gu+'의 지명·지역 연혁 자료. 원문 위치를 지정한 사실 요약 '+str(len(prepared))+'개. 내용 검토와 개별 주소 연결은 미완료.','publicationDate':'','subjectPeriod':'여러 시기 · 지명 유래·지역 형성·연혁','rights':rights,'rightsUrl':url if rights=='KOGL1' else '', 'rightsNote':note,'storageAllowed':rights=='KOGL1','reuseAllowed':rights=='KOGL1','reviewStatus':'needs_review','regionIds':['gu-'+gu]},'metadata':{'원문표제':title,'제공기관':gu+'청','확인방법':method,'원문위치목록':' / '.join(x['locator'] for x in prepared),'시기':'','자료성격':'웹 지역사 · 사실 요약, 원문 전사 없음','원전대조상태':'추가 검토 대기','내용검토주의':notes or '공식 소개의 전승·추정을 확정 사실로 바꾸지 않음. 현재 시설·인구 및 상대 시점 표현은 요약에서 제외.'},'description':'','sections':prepared,'sourceLocator':prepared[0]['locator'],'attribution':gu+'청 · '+title+' · '+url+' · '+CHECKED+' 확인 · '+('공공누리 제1유형 · ' if rights=='KOGL1' else '')+'별도 작성한 사실 요약','rightsEvidence':note,'capturedAt':captured,'pageHash':hashlib.sha256(raw).hexdigest() if raw else ''})

# 서초구: the ten URLs below were observed in the official origin-page tabs.
seocho={
'서초동':('서초동은 서리풀이 자라던 곳이라는 설명과 함께 상초리라는 옛 이름을 소개한다. 구청은 과천군의 서초리·명달리에서 시흥군 신동면을 거쳐 1963년 서울에 편입된 과정을 정리한다. 당산·사도감·왕촌·정곡 등 자연마을의 흔적도 설명한다.','서초동 지명유래 > 첫 문단·옛 마을'),
'잠원동':('조선의 양잠 시설과 관련된 잠실리에서 이어진 지명이다. 서울 편입 당시 다른 잠실동과 구분하려고 잠실과 신원에서 한 글자씩 취했다는 설명이며, 1963년 편입 연혁을 제시한다. 사평장터와 한강진은 지역의 교통·상업 배경으로 소개된다.','잠원동 지명유래 > 첫 문단·사평장터·한강나루'),
'반포동':('굽이치는 개울을 뜻하는 서릿개에서 이름을 찾는 설명과 침수에 연결하는 해석이 함께 전한다. 1963년 서울 편입을 기록하며, 서래마을 형성에 1925년 홍수 이후 이주가 관련된 것으로 소개한다. 서로 다른 어원 설명은 확정하지 않는다.','반포동 지명유래 > 첫 문단·서래마을'),
'방배동':('구청은 우면산을 등진 마을이라는 뜻에서 이름을 설명한다. 과천군 방배리, 1914년 시흥군 신동면, 1963년 서울 편입의 흐름을 제시한다. 남태령의 이름에 관한 정조와 이방의 이야기는 전승으로 다룬다.','방배동 지명유래 > 첫 문단·남태령'),
'양재동':('양재역·양재원과 말죽거리는 여행·운송·상업이 만나는 장소로 소개된다. 구청은 양재천 주변 농경지와 1970년 경부고속도로 개통 이후 택지화를 설명한다. 말죽거리의 어원은 여행자·인조 피란 등 여러 이야기로 전하므로 하나로 확정하지 않는다.','양재동 지명유래 > 첫 문단·말죽거리·양재역'),
'우면동':('우면산 아래 골짜기의 마을이라는 설명에서 이름을 찾는다. 윗우마니·아랫우마니 등 여러 마을이 있었으며, 1970년대 초 도로 건설과 강남 개발 이후 주택과 연구기관이 들어서는 변화를 소개한다. 원문에 적힌 상대 연대는 현재 시점으로 환산하지 않는다.','우면동 지명유래 > 첫 문단'),
'원지동':('조선시대 여행자를 위한 원이 있던 원터에서 이름을 찾는다. 구청은 1963년 편입 당시 바람골·양수리·원터마을을 원지동으로 묶었다고 설명한다. 삼남도로와 여의천 계곡, 경부고속도로 건설에 따른 원터마을의 변화도 소개한다.','원지동 지명유래 > 첫 문단·삼남도로·원터마을'),
'내곡동':('본촌 안쪽의 안골·안말이라는 이름을 한자로 옮긴 지명이다. 헌릉·인릉과 산림, 여러 자연마을을 지역의 배경으로 설명한다. 샘마을은 1972년 와룡동 철거민 이주, 1979년 취락구조개선과 관련된 마을로 소개된다.','내곡동 지명유래 > 내곡동·샘마을'),
'염곡동':('지형을 심장에 빗댄 염통골이라는 이름과 관련된 것으로 설명한다. 1963년 서울 편입과 1988년 서초구 관할 전환을 기록하며 집성촌·옛 우물·취락구조개선을 함께 소개한다. 우물의 약효나 마을의 전쟁 피해에 관한 이야기는 검증된 사실로 사용하지 않는다.','염곡동 지명유래 > 첫 문단·옛 우물·취락구조개선'),
'신원동':('원터 아래에 새로 생긴 마을을 새원이라 부른 데서 이름을 찾는다. 1914년 광주군 언주면 신원리, 1963년 서울 편입, 1988년 서초구 편제의 흐름을 설명한다. 벌말·평촌은 이 지역의 옛 마을 이름으로 소개된다.','신원동 지명유래 > 첫 문단·평촌')}
for n,(text,loc) in seocho.items():
 # Resolve from the cached source's actual hrefs rather than synthesizing route IDs.
 raw=(CACHE/'seocho.html').read_bytes();doc=html.fromstring(raw.decode('utf-8'));url=next(a.get('href') for a in doc.xpath('//a[@href]') if a.text_content().strip()==n and '/1050204' in a.get('href',''))
 add('seocho-'+n,'서초구','서초구 지명유래 · '+n,url,[(n,text,loc)],notes='옛 마을·시설 설명은 자료의 서술 당시 위치 표현이다. 현재 시설 운영·인구·집성촌 규모로 전환하지 않음. 전승과 상대 연대는 추가 검토.')
add('seocho','서초구','서초구의 역사와 지명유래','https://www.seocho.go.kr/site/seocho/05/10502040100002015070810.jsp',[('서초구','구청은 1963년 서울 편입 이후 강남권의 행정구역 변화를 거쳐 1988년 서초구가 분리된 과정을 소개한다. 현대 도시 형성의 배경으로 1965년 도시기본계획과 1968년 영동토지구획정리사업을 설명한다. 구 전체 맥락이며 개별 동이나 필지의 개발 시점을 뜻하지 않는다.','구이름의 역사와 유래 > 행정구역·도시개발 문단')])
add('gwangjin','광진구','광진구 동명유래','https://www.gwangjin.go.kr/portal/main/contents.do?menuNo=200271',[
('중곡동','능동과 면목동 사이의 위치에서 간뎃말·중곡리라는 이름을 설명한다.','동명유래 > 중곡동'),
('능동','순명황후의 유릉이 있던 지역이라는 설명에서 능말·능리라는 이름을 찾는다.','동명유래 > 능동'),
('구의동','구정동과 산의동에서 한 글자씩을 취해 만든 지명으로 설명한다.','동명유래 > 구의동'),
('광장동','광나루 일대 광장리와 장의동의 글자를 결합한 이름으로 소개한다.','동명유래 > 광장동'),
('자양동','암말 사육과 관련된 자마장이라는 이름이 변화한 것으로 설명한다.','동명유래 > 자양동'),
('화양동','화양정에서 이름을 찾는 설명과 단종의 유배에 관한 별도 전승을 소개한다.','동명유래 > 화양동'),
('군자동','1914년 군자리, 1949년 서울 편입, 1950년 군자동으로 이어지는 연혁을 제시한다. 임금의 아들 출생 이야기는 전승이다.','동명유래 > 군자동'),
('노유동','누런산·노룬산 등에 관한 설명이 전한다. 구청은 2008년 자양동 편입을 기록하므로 현재 별도 법정동으로 세지 않는다.','동명유래 > 노유동'),
('모진동','옛 목장과 관련된 전승을 소개한다. 구청은 2009년 화양동 편입을 기록하므로 옛 지명으로 구분한다.','동명유래 > 모진동')],notes='노유동·모진동은 옛 지명 설명으로만 분류. 공식 본문의 행정동·법정동 혼용 가능성과 통합 범위는 추가 대조. 전체 본문 원형 복제 없음.')

add('gangbuk','강북구','강북구 미아동 유래 및 연혁','https://child.gangbuk.go.kr/dong/main/contents.do?dongCd=02&menuNo=600014',[('미아동','지명은 미아리고개 또는 미아사와 관련된 것으로 전하지만 유래가 확실하지 않다고 소개한다. 구청은 1949년 서울 편입 이후 주택지 확대와 인구 증가를 설명한다. 1960년대 전후 도심 철거민·수재민 등의 이주는 삼양동 일대 형성의 배경으로 제시된다.','유래 및 연혁 > 동 유래·삼양동 지역 형성')],notes='현재 행정동 미아동 페이지에서 더 넓은 법정동 미아동의 이름·형성 맥락만 요약. 과거 행정동 번호를 현재 경계로 환산하지 않음.')
add('gangbuk-bun','강북구','강북구 번동 유래 및 연혁','https://child.gangbuk.go.kr/dong/main/contents.do?dongCd=06&menuNo=600103',[('번동','고려 말 오얏나무와 벌리사에 관한 이야기를 어원 전승으로 소개한다. 연혁에는 1949년 서울 편입과 1950년 번리에서 번동으로 이름을 바꾼 내용, 1995년 강북구 관할 전환이 기록되어 있다.','유래 및 연혁 > 동 유래·동 연혁')])
add('gangbuk-ui','강북구','강북구 우이동 유래 및 연혁','https://child.gangbuk.go.kr/dong/main/contents.do?dongCd=12&menuNo=600205',[('우이동','소의 귀처럼 보이는 봉우리와 관련된 이름으로 전한다. 구청은 1751년 도성삼군문분계총목록과 1867년 육전조례의 우이동 표기를 소개한다. 산지와 계곡을 따라 형성된 마을이라는 공간 맥락을 설명한다.','유래 및 연혁 > 동 유래 > 옛 문헌·산지 마을')],notes='본문의 도선사 조성 시기·왕대·북한산국립공원 지정 연도는 다른 기록 대조가 필요하여 요약에서 제외. 과거 시설·행정동의 현재 유효성 미확정.')
add('gangbuk-suyu','강북구','강북구 수유동 유래 및 연혁','https://child.gangbuk.go.kr/dong/main/contents.do?dongCd=10&menuNo=600171',[('수유동','물이 넘치는 마을이라는 무너미와 물길에 관한 다른 이야기가 함께 전한다. 무너미·빨래골·가오리 등 자연마을이 지역의 배경이며, 구청은 1960년 이후 인구 유입과 농촌에서 주택지로의 변화를 설명한다. 빨래골의 도심 철거민 이주도 소개한다.','유래 및 연혁 > 동 유래 > 자연마을·주거지 변화')])

add('gwanak','관악구','관악구 지역특성 · 법정동 지명과 유래','https://www.gwanak.go.kr/site/gwanak/11/11101020000002016051207.jsp',[
('봉천동','관악산의 높은 지세에 연결한 이름으로 설명한다. 당곡·호리목·원당 등 옛 마을과 고개를 소개한다. 표에 있는 은천동·행운동 등은 행정동 명칭으로 구분한다.','지역특성 > 봉천동 > 지명유래'),
('남현동','남쪽 고개인 남태령과 관련된 지명으로 설명한다. 남태령의 어원에 관한 정조 행차 이야기는 전승으로 구분한다.','지역특성 > 남현동 > 지명유래'),
('신림동','관악산 기슭의 숲에서 이름을 설명한다. 1963년 서울 편입과 서원말·난곡·자하골 등 옛 지역을 소개한다. 본문과 표가 난곡 어원을 다르게 설명하므로 어느 하나로 확정하지 않는다.','지역특성 > 신림동 > 지명유래·행정동 명칭')],notes='행정동 명칭을 법정동으로 신규 생성하지 않음. 난곡 어원은 본문(강홍립 관련 전승)과 표(강서의 호) 사이 차이를 보존하고 결론 보류.')
add('gwanak-namhyeon','관악구','관악구 남현동 연혁','https://www.gwanak.go.kr/site/gwanak/12/11205010200002016051309.jsp',[('남현동','구청은 1980년 4월 1일 관악구 관할 사당1동 지역을 남현동으로 명명한 연혁을 제시한다. 이후 지하철 2·4호선과 관련된 교통 여건 변화를 설명하지만 개별 건물의 연혁으로 연결하지 않는다.','남현동의 유래 및 연혁')])

add('sdm','서대문구','서대문구 동명 유래','https://www.sdm.go.kr/wesdm/history/origin.do',[
('충현동','2008년 북아현3동과 충정로동을 합쳐 만든 행정동이다. 세부 법정동과 구분한다.','동명 유래 > 충현동'),
('충정로2가','구청은 1975년 관할 조정에서 충정로2·3가를 서대문구 지역으로 설명한다.','동명 유래 > 충현동 > 1975년 관할 조정','충정로2, 3가'),
('충정로3가','충정로 명칭은 민영환의 시호와 연결되며, 1975년 2·3가 관할 설명이 있다.','동명 유래 > 충현동 > 충정로 명칭·관할','충정로2, 3가'),
('천연동','천연정에서 이름을 설명한다. 인접 법정동까지 같은 유래로 확대하지 않는다.','동명 유래 > 천연동'),
('북아현동','아이 고개에 관한 어원은 불확실하다고 소개한다. 원문의 연대 순서는 추가 대조한다.','동명 유래 > 북아현동'),
('신촌동','새터말의 변화와 1914년 신촌리, 1946년 신촌동으로 이어지는 이름을 설명한다.','동명 유래 > 신촌동'),
('연희동','연희궁터에 관련된 이름으로 소개한다. 궁터 위치는 원문에서도 추정으로 제시된다.','동명 유래 > 연희동'),
('홍제동','여행자·사신이 머물던 홍제원이 이름의 배경이다.','동명 유래 > 홍제동'),
('홍은동','홍제외리와 은평면의 글자를 결합한 지명이다. 1949년 서울 편입을 기록한다.','동명 유래 > 홍은동'),
('남가좌동','가재울 남쪽 마을이라는 설명이다. 1949년 서울 편입을 제시한다.','동명 유래 > 남가좌동'),
('북가좌동','가재울 북쪽 위치에서 이름을 설명하며, 1914년 북가좌리 연혁을 제시한다.','동명 유래 > 북가좌동')],rights='KOGL1',notes='북아현동 문단의 1964년·1955년 서술 순서와 천연동 문단의 행정동·법정동 표현이 혼재함. 이를 교정한 사실로 쓰지 않고 검토 대기로 보존. 현재 행정동 체계로 자동 환산하지 않음.')

add('ydp-origin','영등포구','영등포구 동 명칭 및 지명 유래','https://www.ydp.go.kr/www/contents.do?key=2887',[
('영등포동','영등굿과 물가를 뜻하는 포를 연결한 설명이나 어원은 확실하지 않다고 밝힌다.','동 명칭 및 지명 유래 > 영등포동'),
('여의동','높은 양말산과 섬 이름의 어원을 설명하는 전승이 실려 있다. 행정동·섬·법정동을 구분한다.','동 명칭 및 지명 유래 > 여의동'),
('당산동','해당화 또는 부군당과 제사에서 이름을 찾는 설명이 함께 있다.','동 명칭 및 지명 유래 > 당산동'),
('당산동1가','구청은 이 일대의 불탄 자리라는 옛 지명을 한국전쟁 때 폭격과 연결한다.','동 명칭 및 지명 유래 > 당산동 > 불탄 자리','당산동 1가'),
('도림동','도야미리라는 이름 또는 들판의 식물에서 유래를 설명한다. 어느 하나로 확정하지 않는다.','동 명칭 및 지명 유래 > 도림동'),
('문래동','1930년대 방적공장과 물레에서 어원을 설명한다. 별도 동 소개의 문익점 설과 차이가 있다.','동 명칭 및 지명 유래 > 문래동'),
('문래동4가','오백채는 1940년 무렵 집단 기와집을 조성한 영단주택 지역으로 소개된다.','동 명칭 및 지명 유래 > 문래동 > 오백채','문래동 4가'),
('양평동','양화도 나루와 인근 벌판을 합쳐 이름을 설명한다. 세부 가 단위의 연혁은 구분한다.','동 명칭 및 지명 유래 > 양평동'),
('양화동','옛 나루 주변의 버드나무가 이름의 배경으로 소개된다.','동 명칭 및 지명 유래 > 양화동'),
('신길동','좋은 일을 바라는 이름이라는 추정이 있다. 가마골·밤동산 등 옛 마을도 소개한다.','동 명칭 및 지명 유래 > 신길동'),
('대림동','신대방과 신도림에서 글자를 취한 이름이다. 원지막·은모래길 등 옛 지명도 설명한다.','동 명칭 및 지명 유래 > 대림동')],notes='공통 문래동 설명을 문래동1~6가에 복제하지 않음. 별도 문래동 페이지는 문익점 관련 설을 소개하여 어원 상충 검토 필요. 여의동은 원문의 행정동 표기 그대로 보존.')
add('ydp','영등포구','영등포구 신길동 동유래','https://www.ydp.go.kr/www/contents.do?key=3100',[('신길동','구청은 방학호진 나루와 농업 생활을 지역의 배경으로 소개한다. 신길이라는 이름의 정확한 유래는 알 수 없으며 좋은 일을 바라는 의미라는 추정을 제시한다. 가마골과 밤동산은 옛 마을의 지명으로 설명된다.','신길1동 동유래 > 신길동·가마골·밤동산')])

mapo={
'공덕동':'언덕을 뜻하는 옛말과 공덕리 등 여러 어원 설명이 있어 확정하지 않는다.',
'신공덕동':'공덕리와 인근 신동을 합친 이름으로 소개된다.',
'도화동':'복숭아꽃과 복사골이라는 이름을 연결한다. 주거지 형성 연대는 추가 검토한다.',
'마포동':'마포나루와 삼개라는 옛 이름을 지명의 배경으로 설명한다.',
'토정동':'이지함의 호에서 이름을 가져온 것으로 소개한다.',
'용강동':'용산·서강 또는 지세에서 어원을 찾는 설명과 옹기 생산 이야기가 함께 있다.',
'신수동':'수철리와 무쇠막이라는 옛 이름을 철제 생활도구 생산에 연결한다.',
'구수동':'수철리 주변의 옛 마을이며 무쇠막·무수막이라는 이름을 함께 소개한다.',
'현석동':'박세채의 호 또는 검은 돌에 연결하는 두 어원 설명이 전한다.',
'신정동':'새우물과 서강나루의 세금 관련 관청 터를 소개한다.',
'대흥동':'옹기 생산과 동막역·철도에 따른 마을 변화를 설명한다.',
'염리동':'마포나루의 소금 유통과 소금장수의 거주가 이름의 배경으로 소개된다.',
'아현동':'애오개와 아이 고개 또는 작은 고개라는 여러 해석을 제시한다.',
'합정동':'조개우물에서 이름을 찾는다. 우물의 위치·소멸 시기는 별도 대조가 필요하다.',
'망원동':'망원정과 연결된 이름이며 낮은 강변 마을·이주 정착 이야기를 소개한다.',
'서강동':'마포나루에서 양화나루 사이 서강·서호라는 이름을 설명한다. 행정동 맥락이다.',
'하중동':'하중리라는 이름에서 이어지며, 1946년 명칭 변경을 소개한다.',
'당인동':'임진왜란 때의 군대 주둔을 지명에 연결하는 이야기가 전한다.',
'창전동':'광흥창 앞마을이라는 위치가 이름의 배경으로 설명된다.',
'노고산':'산 이름과 서낭당 주변에 관한 여러 설명을 소개한다. 법정동 명칭으로 보정하지 않는다.',
'서교동':'아랫잔다리·서세교리에서 이름의 변화를 설명한다.','동교동':'윗잔다리·동세교리에서 이름의 변화를 설명한다.',
'상수동':'강가의 위쪽 또는 새텃말이라는 여러 어원 설명이 전한다.',
'하수동':'강변 아래쪽 마을이라는 설명이다. 현재 법정동 목록에 자동 대응하지 않는다.',
'연남동':'연희동에서 나뉜 지역의 남쪽 위치를 이름과 연결한다.',
'중동':'가운데 마을이라는 뜻과 조씨의 거주에 관한 설명을 소개한다.',
'성산동':'성을 닮은 산과 성메·성미라는 이름에서 유래를 설명한다.',
'상암동':'수상리와 휴암리에서 한 글자씩 취한 이름이다. 물길·바위에 관한 옛 이름도 소개한다.'}
mapo_sections=[]
